<?php
declare(strict_types=1);
namespace App\Application\QuestionLearning\Service;
use App\Application\QuestionLearning\DTO\Request\CreateQuestionProblemReportRequestDto;use App\Application\QuestionLearning\DTO\Response\QuestionProblemReportResponseDto;use App\Application\QuestionLearning\Mapper\QuestionProblemReportResponseMapper;use App\Domain\QuestionBank\Repository\FrozenQuestionReaderInterface;use App\Domain\QuestionLearning\Entity\QuestionProblemReport;use App\Domain\QuestionLearning\Enum\ProblemReportStatus;use App\Domain\QuestionLearning\Repository\QuestionProblemReportRepositoryInterface;
final readonly class CreateQuestionProblemReportService { public function __construct(private FrozenQuestionReaderInterface $questions, private QuestionProblemReportRepositoryInterface $reports, private QuestionProblemReportResponseMapper $mapper) {} public function execute(string $userId, CreateQuestionProblemReportRequestDto $request, \DateTimeImmutable $now): QuestionProblemReportResponseDto { if (count($this->questions->findByIds([$request->questionId])) !== 1) { throw new \DomainException('Questão não encontrada.'); } $report = new QuestionProblemReport($this->uuid(), $request->questionId, $userId, $request->category, $request->description, ProblemReportStatus::OPEN, $now, $now); $this->reports->save($report); $this->reports->appendStatusEvent($report->id, $userId, null, ProblemReportStatus::OPEN, $now); return $this->mapper->toResponse($report); } private function uuid(): string { $bytes = random_bytes(16); $bytes[6] = chr((ord($bytes[6]) & 15) | 64); $bytes[8] = chr((ord($bytes[8]) & 63) | 128); return vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($bytes), 4)); } }
